package org.eclipse.jface.internal.text.html;

public class HTML2TextReader {
    private static String[] fgEntityLookup = { "amp", "&", "lt", "<", "gt", ">", "nbsp", " ", "apos", "'", "quot", "\"", "agrave", "\u00e0" };

    protected String entity2Text(String symbol) {
        if (symbol.length() > 1 && symbol.charAt(0) == '#') {
            int i= Integer.parseInt(symbol.substring(1));
            return String.valueOf((char) i);
        }

        for (int i= 0; i < fgEntityLookup.length; i= i + 2) {
            if (symbol.equals(fgEntityLookup[i]))
                return fgEntityLookup[i + 1];
        }
        return "&" + symbol; // not found
    }
}

